UPDATE sys_file SET biz_type = 'HR_SEVERANCE_POLICY', biz_id = #{identifier}, file_hash = #{hash}
WHERE tenant_id = #{tenantId} AND file_id = #{fileId} AND file_type = 'HR_SEVERANCE_POLICY'
  AND deleted = 0 AND biz_type IS NULL AND biz_id IS NULL AND url = '' AND create_by = #{uploader}

UPDATE sys_file SET deleted = 1 WHERE tenant_id = #{tenantId} AND file_id = #{fileId}
  AND file_type = 'HR_SEVERANCE_POLICY' AND biz_type = 'HR_SEVERANCE_POLICY' AND biz_id = #{identifier}
  AND deleted = 0 AND url = ''
